handlers.onSend:
() => {
          const t = this.state.noteDraft.trim();
          if (!t) { this.toast('Enter a note before saving.', '', null); return; }
          this.setState((s) => ({notes: [{title:'Note added', meta:'James Smith · 09/09/2026 08:24', body: t}].concat(s.notes), noteDraft: ''}));
          this.toast('Note added to PN/CC/000622.', '', null);
        }

() => {
          const t = this.state.msgDraft.trim();
          if (!t) { this.toast('Write a message before sending.', '', null); return; }
          this.setState((s) => ({messages: s.messages.concat([{who:'James Smith · Cover MGA', tag:'External', when:'09/09/2026 08:31', body: t, attach:''}]), msgDraft: ''}));
          this.toast('Reply sent to Brightside and logged against the policy.', '', null);
        }

